    // Quick lookup: binary search returns dir at loc, or 0 if no lane
    inline int8_t get_lane_dir(int loc) {
        // Binary search in LANE_TABLE
        int lo = 0, hi = LANE_CELLS - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (LANE_TABLE[mid].loc == loc) return LANE_TABLE[mid].dir;
            if (LANE_TABLE[mid].loc < loc) lo = mid + 1;
            else hi = mid - 1;
        }
        return 0;
    }
